/* @autogenerated */
package net.civeira.phylax.common.infrastructure.config;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assumptions.assumeFalse;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.attribute.PosixFilePermissions;
import java.util.List;
import java.util.Map;

import org.eclipse.microprofile.config.Config;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import io.smallrye.config.SmallRyeConfig;

@DisplayName("IsolatedConfigLoader edge cases")
class IsolatedConfigLoaderEdgeCasesUnitTest {

  @TempDir
  Path external;

  @Test
  @DisplayName("Should build from the application config and the external location")
  void shouldBuildFromApplicationConfig() {
    // Arrange — an application config exposing its active profiles
    SmallRyeConfig smallrye = mock(SmallRyeConfig.class);
    when(smallrye.getProfiles()).thenReturn(List.of("test"));
    Config config = mock(Config.class);
    when(config.unwrap(SmallRyeConfig.class)).thenReturn(smallrye);

    // Act — build the loader through its injection constructor and load a missing file
    IsolatedConfigLoader loader = new IsolatedConfigLoader(config, external.toString());

    // Assert — a missing file yields an empty configuration
    assertFalse(loader.load("isolated-config/does-not-exist.yaml").exists());
  }

  @Test
  @DisplayName("Should report an external file that cannot be read")
  void shouldReportUnreadableExternalFile() throws IOException {
    // Arrange — an external yaml without read permission
    Path file = external.resolve("unreadable.yaml");
    Files.writeString(file, "key: value\n");
    Files.setPosixFilePermissions(file, PosixFilePermissions.fromString("-w-------"));
    assumeFalse(Files.isReadable(file), "the current user can read files without permission");
    IsolatedConfigLoader loader = new IsolatedConfigLoader(external, List.of(), Map.of());

    // Act / Assert — the read error is reported as unchecked
    assertThrows(UncheckedIOException.class, () -> loader.load("unreadable.yaml"));
  }
}
